"""Legacy Extract Adapter: parses the mainframe's fixed-width settlement extract."""
from dataclasses import dataclass

FIELDS = (("txn_id", 0, 12), ("card_token", 12, 28), ("amount_cents", 28, 38),
          ("mcc", 38, 42), ("country", 42, 44), ("hour", 44, 46))
RECORD_LENGTH = 46


@dataclass(frozen=True)
class Transaction:
    txn_id: str
    card_token: str
    amount_cents: int
    mcc: str
    country: str
    hour: int


@dataclass(frozen=True)
class ParseError:
    line_number: int
    reason: str


def parse_extract(lines):
    """Return (transactions, errors). Malformed records are reported, never dropped."""
    transactions, errors = [], []
    for number, raw in enumerate(lines, start=1):
        line = raw.rstrip("\n")
        if not line.strip():
            continue
        if len(line) != RECORD_LENGTH:
            errors.append(ParseError(number, f"expected {RECORD_LENGTH} chars, got {len(line)}"))
            continue
        values = {name: line[start:end].strip() for name, start, end in FIELDS}
        try:
            transactions.append(Transaction(
                txn_id=values["txn_id"], card_token=values["card_token"],
                amount_cents=int(values["amount_cents"]), mcc=values["mcc"],
                country=values["country"], hour=int(values["hour"]),
            ))
        except ValueError as exc:
            errors.append(ParseError(number, str(exc)))
    return transactions, errors

"""Fraud Scoring Engine + Hold File Writer (explainable weighted rules)."""
HIGH_RISK_MCC = {"7995", "4829", "6051"}


def score(txn, home_country="US"):
    """Return (score 0-1000, reason codes)."""
    points, reasons = 0, []
    if txn.amount_cents >= 500_000:
        points += 400
        reasons.append("R01_HIGH_AMOUNT")
    if txn.mcc in HIGH_RISK_MCC:
        points += 300
        reasons.append("R02_HIGH_RISK_MCC")
    if txn.country != home_country:
        points += 200
        reasons.append("R03_FOREIGN_COUNTRY")
    if txn.hour < 5:
        points += 100
        reasons.append("R04_UNUSUAL_HOUR")
    return min(points, 1000), reasons


def build_hold_file(transactions, threshold=600):
    """Hold records in the mainframe's inbound fixed-width layout: id(12) score(4) reasons(40)."""
    lines = []
    for txn in transactions:
        value, reasons = score(txn)
        if value >= threshold:
            lines.append(f"{txn.txn_id:<12}{value:04d}{','.join(reasons[:3]):<40}")
    return lines
